package online.fanous.satellite;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.content.pm.ServiceInfo;
import android.graphics.ImageFormat;
import android.hardware.*;
import android.hardware.camera2.*;
import android.hardware.camera2.params.StreamConfigurationMap;
import android.location.*;
import android.media.Image;
import android.media.ImageReader;
import android.os.*;
import android.util.Size;
import android.view.WindowManager;
import org.json.*;
import java.nio.*;
import java.util.*;
import java.util.concurrent.*;
import okhttp3.*;
import okio.ByteString;
public final class TelemetryService extends Service implements SensorEventListener,LocationListener {
    public static volatile boolean running=false,connected=false,cameraActive=false;
    private final OkHttpClient client=new OkHttpClient.Builder().pingInterval(20,TimeUnit.SECONDS).build();
    private final ScheduledExecutorService ticker=Executors.newSingleThreadScheduledExecutor();
    private SensorManager sensors;private LocationManager locations;private PowerManager.WakeLock wake;private long wakeAt;
    private volatile float[] accel,gyro,mag;private volatile double[] quaternion;private volatile boolean absolute=false,relay=false,stopped=false,connecting=false;
    private volatile JSONObject gps;private volatile WebSocket socket;private volatile long retryAt=0;private long seq=0,lastSend=0,lastCamera=0;
    private HandlerThread cameraThread;private Handler cameraHandler;private CameraDevice camera;private CameraCaptureSession session;private ImageReader reader;private int cameraRotation=90,jpegWidth=640,jpegHeight=480;private volatile boolean cameraWanted=false,capturePending=false;private boolean rotationVectorAvailable=false;private double shortFovDegrees=50;
    private final ArrayDeque<Pose> poses=new ArrayDeque<>();private static final class Pose{long at;double[] q;Pose(long a,double[] b){at=a;q=b.clone();}}
    @Override public void onCreate(){super.onCreate();NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("relay","Fanous satellite relay",NotificationManager.IMPORTANCE_LOW));sensors=(SensorManager)getSystemService(SENSOR_SERVICE);locations=(LocationManager)getSystemService(LOCATION_SERVICE);wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"fanous:satellite-relay");cameraThread=new HandlerThread("FanousCamera");cameraThread.start();cameraHandler=new Handler(cameraThread.getLooper());}
    private boolean locationAllowed(){return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
    private void foreground(boolean withCamera){Intent stop=new Intent(this,TelemetryService.class).setAction("STOP");PendingIntent action=PendingIntent.getService(this,1,stop,PendingIntent.FLAG_IMMUTABLE);PendingIntent open=PendingIntent.getActivity(this,2,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(this,"relay").setSmallIcon(R.drawable.satellite_icon).setContentTitle("Fanous satellite relay").setContentText(withCamera?"Sensors, location and rear camera active":"Phone sensor relay active — tap to manage").setContentIntent(open).setOngoing(true).addAction(new Notification.Action.Builder(null,"Stop",action).build()).build();if(Build.VERSION.SDK_INT>=34){int type=locationAllowed()?ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION:ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE;if(withCamera)type|=ServiceInfo.FOREGROUND_SERVICE_TYPE_CAMERA;startForeground(41,n,type);}else startForeground(41,n);}
    @Override public int onStartCommand(Intent intent,int flags,int startId){String action=intent==null?"STOP":intent.getAction();if("STOP".equals(action)){stopSelf();return START_NOT_STICKY;}if(PrivateStore.get(this,"token").isEmpty()){stopSelf();return START_NOT_STICKY;}
        try{foreground("CAMERA_ON".equals(action)||cameraWanted);}catch(SecurityException e){stopSelf();return START_NOT_STICKY;}
        running=true;if(lastSend==0){registerSensors();requestLocation();wake.acquire(600000);wakeAt=SystemClock.elapsedRealtime();lastSend=1;ticker.scheduleWithFixedDelay(this::tick,0,50,TimeUnit.MILLISECONDS);}
        if("CAMERA_ON".equals(action)&&checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED){relay=false;cameraWanted=true;openCamera();}
        if("CAMERA_OFF".equals(action)){cameraWanted=false;closeCamera();foreground(false);}
        if("RELAY".equals(action)){relay=true;cameraWanted=false;closeCamera();foreground(false);registerSensors();}
        if("START".equals(action)){relay=false;registerSensors();}
        return START_NOT_STICKY;
    }
    private void registerSensors(){sensors.unregisterListener(this);int delay=relay?40000:20000;for(int type:new int[]{Sensor.TYPE_ACCELEROMETER,Sensor.TYPE_GYROSCOPE,Sensor.TYPE_MAGNETIC_FIELD}){Sensor s=sensors.getDefaultSensor(type);if(s!=null)sensors.registerListener(this,s,delay);}Sensor rotation=sensors.getDefaultSensor(Sensor.TYPE_ROTATION_VECTOR);rotationVectorAvailable=rotation!=null;if(rotation==null)rotation=sensors.getDefaultSensor(Sensor.TYPE_GAME_ROTATION_VECTOR);if(rotation!=null)sensors.registerListener(this,rotation,delay);}
    private void requestLocation(){if(!locationAllowed())return;for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER})try{if(locations.isProviderEnabled(provider))locations.requestLocationUpdates(provider,1000,0,this);}catch(SecurityException|IllegalArgumentException ignored){}}
    @Override public void onSensorChanged(SensorEvent e){if(stopped)return;switch(e.sensor.getType()){
      case Sensor.TYPE_ACCELEROMETER:accel=Arrays.copyOf(e.values,3);break;case Sensor.TYPE_GYROSCOPE:gyro=Arrays.copyOf(e.values,3);break;case Sensor.TYPE_MAGNETIC_FIELD:mag=Arrays.copyOf(e.values,3);break;
      case Sensor.TYPE_ROTATION_VECTOR:case Sensor.TYPE_GAME_ROTATION_VECTOR:float[] out=new float[4];SensorManager.getQuaternionFromVector(out,e.values);quaternion=new double[]{out[1],out[2],out[3],out[0]};absolute=e.sensor.getType()==Sensor.TYPE_ROTATION_VECTOR;synchronized(poses){poses.addLast(new Pose(e.timestamp,quaternion));while(poses.size()>200)poses.removeFirst();}break;
    }
    if(!rotationVectorAvailable&&accel!=null&&mag!=null){float[] matrix=new float[9];if(SensorManager.getRotationMatrix(matrix,null,accel,mag)){quaternion=fromMatrix(matrix);absolute=true;synchronized(poses){poses.addLast(new Pose(e.timestamp,quaternion));while(poses.size()>200)poses.removeFirst();}}}}
    private double[] fromMatrix(float[] m){double x,y,z,w,t=m[0]+m[4]+m[8];if(t>0){double s=Math.sqrt(t+1)*2;w=s/4;x=(m[7]-m[5])/s;y=(m[2]-m[6])/s;z=(m[3]-m[1])/s;}else if(m[0]>m[4]&&m[0]>m[8]){double s=Math.sqrt(1+m[0]-m[4]-m[8])*2;x=s/4;y=(m[1]+m[3])/s;z=(m[2]+m[6])/s;w=(m[7]-m[5])/s;}else if(m[4]>m[8]){double s=Math.sqrt(1+m[4]-m[0]-m[8])*2;y=s/4;x=(m[1]+m[3])/s;z=(m[5]+m[7])/s;w=(m[2]-m[6])/s;}else{double s=Math.sqrt(1+m[8]-m[0]-m[4])*2;z=s/4;x=(m[2]+m[6])/s;y=(m[5]+m[7])/s;w=(m[3]-m[1])/s;}double n=Math.sqrt(x*x+y*y+z*z+w*w);return new double[]{x/n,y/n,z/n,w/n};}
    @Override public void onAccuracyChanged(Sensor sensor,int accuracy){}
    @Override public void onLocationChanged(Location l){try{JSONObject p=new JSONObject().put("lat",l.getLatitude()).put("lon",l.getLongitude()).put("accuracy",l.getAccuracy()).put("at",l.getTime()).put("altitude",l.hasAltitude()?l.getAltitude():JSONObject.NULL).put("altitudeAccuracy",Build.VERSION.SDK_INT>=26&&l.hasVerticalAccuracy()?l.getVerticalAccuracyMeters():JSONObject.NULL).put("speed",l.hasSpeed()?l.getSpeed():JSONObject.NULL).put("course",l.hasBearing()?l.getBearing():JSONObject.NULL);gps=p;}catch(JSONException ignored){}}
    @Override public void onProviderEnabled(String provider){}@Override public void onProviderDisabled(String provider){}@Override public void onStatusChanged(String provider,int status,Bundle extras){}
    private JSONArray vector(float[] v){if(v==null)return null;JSONArray a=new JSONArray();for(float x:v)try{a.put((double)x);}catch(JSONException ignored){}return a;}
    private JSONArray vector(double[] v){if(v==null)return null;JSONArray a=new JSONArray();for(double x:v)try{a.put(x);}catch(JSONException ignored){}return a;}
    private int screenAngle(){return ((WindowManager)getSystemService(WINDOW_SERVICE)).getDefaultDisplay().getRotation()*90;}
    private void connect(){if(connecting||stopped||System.currentTimeMillis()<retryAt)return;connecting=true;Request req=new Request.Builder().url("wss://fanous.online/satellite-api/device").header("Authorization","Bearer "+PrivateStore.get(this,"token")).build();socket=client.newWebSocket(req,new WebSocketListener(){@Override public void onOpen(WebSocket ws,Response response){if(stopped){ws.close(1000,"Stopped");return;}socket=ws;connected=true;connecting=false;retryAt=0;}@Override public void onFailure(WebSocket ws,Throwable t,Response response){if(socket==ws){socket=null;connected=false;}connecting=false;retryAt=System.currentTimeMillis()+5000;if(response!=null&&response.code()==401){PrivateStore.clear(TelemetryService.this);stopSelf();}}@Override public void onClosing(WebSocket ws,int code,String reason){connected=false;ws.close(code,reason);if(code==1008){PrivateStore.clear(TelemetryService.this);stopSelf();}}@Override public void onClosed(WebSocket ws,int code,String reason){if(socket==ws){socket=null;connected=false;}connecting=false;retryAt=System.currentTimeMillis()+2000;if(code==1008){PrivateStore.clear(TelemetryService.this);stopSelf();}}});}
    private void tick(){try{if(stopped)return;if(SystemClock.elapsedRealtime()-wakeAt>300000){if(wake.isHeld())wake.release();wake.acquire(600000);wakeAt=SystemClock.elapsedRealtime();}if(socket==null){connect();return;}long now=System.currentTimeMillis();if(now-lastSend<(relay?200:100))return;lastSend=now;Intent battery=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));double level=battery==null?0:(double)battery.getIntExtra(BatteryManager.EXTRA_LEVEL,0)/Math.max(1,battery.getIntExtra(BatteryManager.EXTRA_SCALE,100));JSONObject p=new JSONObject().put("type","telemetry").put("seq",++seq).put("at",now).put("accel",accel==null?JSONObject.NULL:vector(accel)).put("gyro",gyro==null?JSONObject.NULL:vector(gyro)).put("mag",mag==null?JSONObject.NULL:vector(mag)).put("q",quaternion==null?JSONObject.NULL:vector(quaternion)).put("absolute",absolute).put("gps",gps==null?JSONObject.NULL:gps).put("battery",level).put("relay",relay).put("screenAngle",screenAngle());if(socket.queueSize()<128000)socket.send(p.toString());if(cameraWanted&&!relay&&session!=null&&now-lastCamera>1000&&!capturePending){lastCamera=now;capturePending=true;cameraHandler.post(this::capture);}}catch(Exception ignored){}}
    private void openCamera(){cameraHandler.post(()->{if(camera!=null||!cameraWanted)return;try{CameraManager manager=(CameraManager)getSystemService(CAMERA_SERVICE);String rear=null;for(String id:manager.getCameraIdList()){Integer lens=manager.getCameraCharacteristics(id).get(CameraCharacteristics.LENS_FACING);if(lens!=null&&lens==CameraCharacteristics.LENS_FACING_BACK){rear=id;break;}}if(rear==null){cameraWanted=false;return;}CameraCharacteristics c=manager.getCameraCharacteristics(rear);Integer rotation=c.get(CameraCharacteristics.SENSOR_ORIENTATION);cameraRotation=rotation==null?90:rotation;StreamConfigurationMap map=c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);Size chosen=null;if(map!=null)for(Size size:map.getOutputSizes(ImageFormat.JPEG)){if(size.getWidth()*size.getHeight()>=640*480&&(chosen==null||size.getWidth()*size.getHeight()<chosen.getWidth()*chosen.getHeight()))chosen=size;}if(chosen!=null){jpegWidth=chosen.getWidth();jpegHeight=chosen.getHeight();}android.util.SizeF physical=c.get(CameraCharacteristics.SENSOR_INFO_PHYSICAL_SIZE);float[] focal=c.get(CameraCharacteristics.LENS_INFO_AVAILABLE_FOCAL_LENGTHS);if(physical!=null&&focal!=null&&focal.length>0&&focal[0]>0){double aspect=(double)jpegWidth/jpegHeight;double cropW=Math.min(physical.getWidth(),physical.getHeight()*aspect),cropH=cropW/aspect;shortFovDegrees=Math.toDegrees(2*Math.atan(Math.min(cropW,cropH)/(2*focal[0])));}reader=ImageReader.newInstance(jpegWidth,jpegHeight,ImageFormat.JPEG,2);reader.setOnImageAvailableListener(r->{try(Image image=r.acquireLatestImage()){capturePending=false;if(image==null||!cameraWanted||socket==null)return;ByteBuffer b=image.getPlanes()[0].getBuffer();byte[] jpg=new byte[b.remaining()];b.get(jpg);if(jpg.length>260000)return;double[] pose=quaternion;long best=Long.MAX_VALUE;synchronized(poses){for(Pose item:poses){long diff=Math.abs(item.at-image.getTimestamp());if(diff<best){best=diff;pose=item.q;}}}if(pose==null)return;int rotationDegrees=(cameraRotation-screenAngle()+360)%360;JSONObject meta=new JSONObject().put("type","camera").put("at",System.currentTimeMillis()).put("q",vector(pose)).put("absolute",absolute).put("screenAngle",screenAngle()).put("width",rotationDegrees%180==0?jpegWidth:jpegHeight).put("height",rotationDegrees%180==0?jpegHeight:jpegWidth).put("shortFovDegrees",shortFovDegrees).put("attitudeAgeMs",best<1000000000L?best/1000000:-1);byte[] header=meta.toString().getBytes("UTF-8");ByteBuffer packet=ByteBuffer.allocate(4+header.length+jpg.length).order(ByteOrder.BIG_ENDIAN);packet.putInt(header.length).put(header).put(jpg);WebSocket ws=socket;if(ws!=null&&ws.queueSize()<200000)ws.send(ByteString.of(packet.array()));}catch(Exception ignored){capturePending=false;}},cameraHandler);if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){cameraWanted=false;return;}manager.openCamera(rear,new CameraDevice.StateCallback(){@Override public void onOpened(CameraDevice device){if(!cameraWanted){device.close();return;}camera=device;cameraActive=true;try{device.createCaptureSession(Collections.singletonList(reader.getSurface()),new CameraCaptureSession.StateCallback(){@Override public void onConfigured(CameraCaptureSession s){session=s;}@Override public void onConfigureFailed(CameraCaptureSession s){closeCamera();}},cameraHandler);}catch(Exception e){closeCamera();}}@Override public void onDisconnected(CameraDevice d){d.close();camera=null;session=null;}@Override public void onError(CameraDevice d,int error){d.close();camera=null;session=null;}},cameraHandler);}catch(Exception e){cameraWanted=false;closeCamera();}});}
    private void capture(){try{if(camera==null||session==null||reader==null){capturePending=false;return;}CaptureRequest.Builder request=camera.createCaptureRequest(CameraDevice.TEMPLATE_STILL_CAPTURE);request.addTarget(reader.getSurface());request.set(CaptureRequest.JPEG_QUALITY,(byte)60);request.set(CaptureRequest.JPEG_ORIENTATION,(cameraRotation-screenAngle()+360)%360);request.set(CaptureRequest.CONTROL_AF_MODE,CaptureRequest.CONTROL_AF_MODE_CONTINUOUS_PICTURE);session.capture(request.build(),new CameraCaptureSession.CaptureCallback(){@Override public void onCaptureFailed(CameraCaptureSession s,CaptureRequest r,CaptureFailure f){capturePending=false;}},cameraHandler);}catch(Exception ignored){capturePending=false;}}
    private void closeCamera(){cameraActive=false;cameraHandler.post(()->{if(session!=null){session.close();session=null;}if(camera!=null){camera.close();camera=null;}if(reader!=null){reader.close();reader=null;}capturePending=false;});}
    @Override public void onDestroy(){running=false;connected=false;cameraActive=false;stopped=true;cameraWanted=false;ticker.shutdownNow();sensors.unregisterListener(this);try{locations.removeUpdates(this);}catch(SecurityException ignored){}WebSocket ws=socket;socket=null;if(ws!=null)ws.close(1000,"Phone stopped");closeCamera();cameraThread.quitSafely();if(wake.isHeld())wake.release();stopForeground(STOP_FOREGROUND_REMOVE);client.dispatcher().executorService().shutdown();super.onDestroy();}
    @Override public IBinder onBind(Intent intent){return null;}
}
